    'trust_safety' => [
        'caption' => ':community',
        'title' => 'Vertrauen und Sicherheit',
        'subtitle' => ':name verbindet Nachbarn, damit sie ihre Fähigkeiten mithilfe von Zeitguthaben teilen können. Auf dieser Seite wird erklärt, wie das in der Praxis funktioniert – was die Plattform kann, was nicht und wie Sie sicher bleiben können.',
        'safeguarding_title' => 'Melden Sie ein Sicherheitsbedenken',
        'safeguarding_body' => 'Wenn Sie sich Sorgen über ein Mitglied, einen Austausch oder etwas, das Sie auf der Plattform gesehen haben, machen, teilen Sie uns dies bitte mit. Wir reagieren auf Schutzmeldungen innerhalb eines Werktages.',
        'sections' => [
            'vetting_attestation' => [
                'heading' => 'Bestätigungen zur Sicherheitsüberprüfung der Gemeinschaft',
                'intro' => 'Einige Richtlinien für den Kontakt in der Gemeinschaft erfordern die Bestätigung einer Sicherheitsüberprüfung.',
                'items' => [
                    '0' => 'Die Gemeinschaft führt jegliche rechtmäßige Überprüfung außerhalb von Project NEXUS durch.',
