            ],
            'how_exchanges' => [
                'heading' => 'Wie Börsen funktionieren',
                'intro' => 'Der Austausch wird zwischen den Mitgliedern vereinbart. Hier ist der übliche Ablauf.',
                'items' => [
                    '0' => 'Finden Sie ein Mitglied, das das anbietet, was Sie brauchen, oder stellen Sie eine Anfrage, in der beschrieben wird, wonach Sie suchen.',
                    '1' => 'Senden Sie ihnen über die Plattform eine Nachricht, um die Details zu vereinbaren – Zeit, Ort und alles, was damit zu tun hat.',
                    '2' => 'Schließen Sie den Austausch ab. Persönlich trifft man sich nur, wenn man es beide möchte.',
                    '3' => 'Protokollieren Sie die Stunden. Beide Mitglieder bestätigen – das ist die Quittung.',
