            'what_we_do' => [
                'heading' => 'Was wir tun',
                'intro' => '',
                'items' => [
                    '0' => 'Verifizieren Sie bei der Registrierung die E-Mail-Adresse jedes Mitglieds und bieten Sie optional die Verifizierung eines Lichtbildausweises mit einem Abzeichen für verifizierte Mitglieder an.',
                    '1' => 'Zeigen Sie Rezensionen und Bewertungen auf Mitgliederprofilen an, damit die Community sehen kann, wer ein zuverlässiger Austauschpartner war.',
                    '2' => 'Bitten Sie jedes Mitglied, unsere Community-Richtlinien und Richtlinien zur akzeptablen Nutzung zu akzeptieren und diese einzuhalten.',
                    '3' => 'Geben Sie jedem Eintrag, jeder Nachricht und jedem Profil eine Meldeschaltfläche, die direkt an die Koordinatoren weitergeleitet wird.',
                    '4' => 'Haben Sie menschliche Koordinatoren, die vermitteln, unterstützen und eingreifen können, wenn etwas schief geht.',
